import math

class Solution:
    def judgeSquareSum(self, c: int) -> bool:
        left, right = 0, int(math.isqrt(c))
        while left <= right:
            cur = left * left + right * right
            if cur == c:
                return True
            elif cur < c:
                left += 1
            else:
                right -= 1
        return False

class Solution {
public:
    bool judgeSquareSum(int c) {
        long long left = 0, right = (long long)sqrt(c);
        while (left <= right) {
            long long cur = left * left + right * right;
            if (cur == c) return true;
            if (cur < c) left++;
            else right--;
        }
        return false;
    }
};

class Solution {
    public boolean judgeSquareSum(int c) {
        long left = 0, right = (long) Math.sqrt(c);
        while (left <= right) {
            long cur = left * left + right * right;
            if (cur == c) return true;
            if (cur < c) left++;
            else right--;
        }
        return false;
    }
}

var judgeSquareSum = function(c) {
    let left = 0, right = Math.floor(Math.sqrt(c));
    while (left <= right) {
        const cur = left * left + right * right;
        if (cur === c) return true;
        if (cur < c) left++;
        else right--;
    }
    return false;
};
